-- finance_export: f_fiscal_qtr is a UC SQL UDF in silver (see foundation).
-- The UNLOAD step lives in export.py (CSV to a UC volume).
CREATE OR REPLACE TABLE gold.finance_monthly AS
SELECT CAST(date_trunc('MONTH', o.order_ts) AS DATE)                AS month,
       CASE WHEN month(o.order_ts) >= 2
            THEN year(o.order_ts)
            ELSE year(o.order_ts) - 1
       END                                                          AS fiscal_year,
       silver.f_fiscal_qtr(CAST(o.order_ts AS DATE))                AS fiscal_qtr,
       COUNT(DISTINCT o.order_id)                                   AS order_count,
       SUM(oi.quantity * (oi.unit_price - oi.discount))             AS revenue
FROM   silver.orders o
JOIN   silver.order_items oi ON oi.order_id = o.order_id
GROUP  BY 1, 2, 3;
